def split_graphemes(text: str) -> list[str]:
    """Split text into a list of graphemes."""
    graphemes = []
    if not text:
        return graphemes

    current_grapheme = []
    for char in text:
        if not current_grapheme:
            current_grapheme.append(char)
        else:
            # If current char is extending/ZWJ, or if previous char was ZWJ
            is_extending = unicodedata.combining(char) or char == "\u200d" or char in ("\uFE0F", "\uFE0E")
            prev_was_zwj = current_grapheme[-1] == "\u200d"

            if is_extending or prev_was_zwj:
